Lemma bv_eqb_refl : forall {n} (x : bv n), bv_eqb x x = true.
Proof.
ltac2:(KReplay.run1 (kr_t_F_stdio_exit ()) [] "h01nh11xp;1p;2p;3p10000p4p7210p1000\p4p710p8g001:j14Tg001]j23Tg002Gj10Tg002ij31Tg003Vj32Tg0040f0R0#4f1R1/30#0g004NA1100g004n32eW1W0o"). Qed.

Ltac if_refl :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ (if bv_eqb ?x ?x then _ else _) _ _ _ _) => rewrite (bv_eqb_refl x); cbv iota
  end.

Ltac if_lit :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) => let v := eval vm_compute in c in change c with v; cbv iota
  end.

